#include "event_bus.hpp"

#include <cassert>
#include <iostream>

int main() {
    {
        EventLog log(10);
        EventBus bus(log, 1);
        int id1 = bus.subscribe("a", [](const Event&) {});
        assert(id1 != -1);
        int id2 = bus.subscribe("a", [](const Event&) {});
        assert(id2 == -1);
    }
    {
        EventLog log(10);
        EventBus bus(log, 1);
        bus.subscribe("full", [](const Event&) {});
        int movable = bus.subscribe("other", [](const Event&) {});

        int result = bus.resubscribe(movable, "full");
        assert(result == 0);
    }
    std::cout << "PASS" << std::endl;
    return 0;
}

