#pragma once

#include <functional>
#include <string>
#include <unordered_map>
#include <utility>

#include "event.hpp"
#include "event_log.hpp"

class EventBus {
public:
    using Callback = std::function<void(const Event&)>;

    explicit EventBus(EventLog& log, int maxSubscribersPerTopic = -1)
        : log_(log), max_subscribers_per_topic_(maxSubscribersPerTopic) {}

    int subscribe(const std::string& topic, Callback cb) {
        if (capReached(topic)) {
            return -1;
        }
        int id = next_id_++;
        subscribers_[id] = std::make_pair(topic, std::move(cb));
        return id;
    }

    void unsubscribe(int subscription_id) { subscribers_.erase(subscription_id); }

    /*
     * Changes an existing subscription's topic. Must ALSO respect the
     * per-topic subscriber cap for the new topic, same as subscribe().
     * Returns 1 on success, 0 if oldId doesn't exist or the new topic
     * is already at capacity (nothing changed in that case).
     */
    int resubscribe(int oldId, const std::string& newTopic) {
        auto it = subscribers_.find(oldId);
        if (it == subscribers_.end()) {
            return 0;
        }
        Callback cb = it->second.second;
        std::string oldTopic = it->second.first;
        subscribers_.erase(it);
        if (capReached(newTopic)) {
            subscribers_[oldId] = std::make_pair(oldTopic, std::move(cb));
            return 0;
        }
        subscribers_[oldId] = std::make_pair(newTopic, std::move(cb));
        return 1;
    }

    int publish(const std::string& topic, const std::string& payload) {
        Event event{next_seq_++, topic, payload};
        log_.record(event);
        int invoked = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                entry.second.second(event);
                invoked++;
            }
        }
        return invoked;
    }

private:
    bool capReached(const std::string& topic) const {
        if (max_subscribers_per_topic_ < 0) {
            return false;
        }
        int count = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                count++;
            }
        }
        return count >= max_subscribers_per_topic_;
    }

    EventLog& log_;
    std::unordered_map<int, std::pair<std::string, Callback>> subscribers_;
    int next_id_ = 1;
    long next_seq_ = 1;
    int max_subscribers_per_topic_;
};

